public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return res;
    }
    boolean[] used = new boolean[nums.length];
    List<Integer> current = new ArrayList<>(nums.length);
    backtrack(nums, used, current, res);
    return res;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> res) {
    if (current.size() == nums.length) {
        res.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            current.add(nums[i]);
            backtrack(nums, used, current, res);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest non-null string to limit substring generation
    String minStr = null;
    for (String s : strings) {
        if (s == null) {
            continue;
        }
        if (minStr == null || s.length() < minStr.length()) {
            minStr = s;
        }
    }
    if (minStr == null || minStr.isEmpty()) {
        return 0;
    }
    int minLen = minStr.length();
    // Iterate over possible lengths from longest to shortest
    for (int len = minLen; len >= 1; len--) {
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        for (int i = 0; i + len <= minLen; i++) {
            String sub = minStr.substring(i, i + len);
            if (seen.contains(sub)) {
                continue;
            }
            seen.add(sub);
            String revSub = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (s == null) {
                    ok = false;
                    break;
                }
                if (!(s.contains(sub) || s.contains(revSub))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

