public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0 || start == null || end == null || paths == null) {
            return "cannot be travelled";
        }
        if (start.length != n || end.length != n) {
            return "cannot be travelled";
        }
        // Validate coordinates are within bounds [0, n-1]
        for (int v : start) {
            if (v < 0 || v >= n) return "cannot be travelled";
        }
        for (int v : end) {
            if (v < 0 || v >= n) return "cannot be travelled";
        }
        // Helper to convert coordinate to unique index
        java.util.function.Function<int[], Integer> coordToIndex = (int[] coord) -> {
            int idx = 0;
            int base = 1;
            for (int i = 0; i < n; i++) {
                idx += coord[i] * base;
                base *= n;
            }
            return idx;
        };
        int startIdx = coordToIndex.apply(start);
        int endIdx = coordToIndex.apply(end);
        if (startIdx == endIdx) return "can be travelled";

        // Build adjacency list
        int maxNodes = (int) Math.pow(n, n); // may be large but assume manageable
        java.util.List<Integer>[] adj = new java.util.ArrayList[maxNodes];
        for (int i = 0; i < maxNodes; i++) {
            adj[i] = new java.util.ArrayList<>();
        }
        for (int[] edge : paths) {
            if (edge == null || edge.length != 2) continue;
            int u = edge[0];
            int v = edge[1];
            if (u < 0 || u >= maxNodes || v < 0 || v >= maxNodes) continue;
            adj[u].add(v);
            adj[v].add(u);
        }

        // BFS
        boolean[] visited = new boolean[maxNodes];
        java.util.ArrayDeque<Integer> queue = new java.util.ArrayDeque<>();
        queue.add(startIdx);
        visited[startIdx] = true;
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            for (int nb : adj[cur]) {
                if (!visited[nb]) {
                    if (nb == endIdx) return "can be travelled";
                    visited[nb] = true;
                    queue.add(nb);
                }
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

public static String convertDatesToWeekdays(String date) {
