public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false; // cannot pair all elements
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // handle negative numbers
        freq[r]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) { // when k is even and r == k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) return 0;
    if (edges == null || hasApple == null) throw new IllegalArgumentException("Null input");
    if (hasApple.length != n) throw new IllegalArgumentException("hasApple length mismatch");
    if (n == 1) return 0;
    if (edges.length != n - 1) throw new IllegalArgumentException("Edges length mismatch");
    int[] degree = new int[n];
    for (int[] e : edges) {
        if (e == null || e.length != 2) throw new IllegalArgumentException("Invalid edge");
        int u = e[0], v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) throw new IllegalArgumentException("Edge node out of bounds");
        degree[u]++; degree[v]++;
    }
    int[][] adj = new int[n][];
    for (int i = 0; i < n; i++) adj[i] = new int[degree[i]];
    int[] idx = new int[n];
    for (int[] e : edges) {
        int u = e[0], v = e[1];
        adj[u][idx[u]++] = v;
        adj[v][idx[v]++] = u;
    }
    int[] time = new int[n];
    int maxStackSize = 2 * n;
    int[] stackNode = new int[maxStackSize];
    int[] stackParent = new int[maxStackSize];
    int[] stackFlag = new int[maxStackSize];
    int sp = 0;
    stackNode[sp] = 0;
    stackParent[sp] = -1;
    stackFlag[sp] = 0;
    sp++;
    while (sp > 0) {
        sp--;
        int node = stackNode[sp];
        int parent = stackParent[sp];
        int flag = stackFlag[sp];
        if (flag == 0) {
            stackNode[sp] = node;
            stackParent[sp] = parent;
            stackFlag[sp] = 1;
            sp++;
            for (int neighbor : adj[node]) {
                if (neighbor != parent) {
                    stackNode[sp] = neighbor;
                    stackParent[sp] = node;
                    stackFlag[sp] = 0;
                    sp++;
                }
            }
        } else {
            int sum = 0;
            for (int neighbor : adj[node]) {
                if (neighbor != parent) {
                    if (time[neighbor] > 0 || hasApple[neighbor]) {
                        sum += time[neighbor] + 2;
                    }
                }
            }
            time[node] = sum;
        }
    }
    return time[0];
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;

    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] sums = new java.util.HashSet[n + 1];
    sums[0] = new java.util.HashSet<>();
    sums[0].add(0);

    for (int i = 0; i < n; i++) {
        int num = nums[i];
        // iterate k from i down to 0 to avoid using updated values in the same iteration
        for (int k = i; k >= 0; k--) {
            if (sums[k] == null) continue;
            java.util.HashSet<Integer> nextSet = sums[k + 1];
            if (nextSet == null) {
                nextSet = new java.util.HashSet<>();
                sums[k + 1] = nextSet;
            }
            for (int sum : sums[k]) {
                nextSet.add(sum + num);
            }
        }
    }

    for (int k = 1; k < n; k++) {
        long prod = (long) totalSum * k;
        if (prod % n != 0) continue;
        int target = (int) (prod / n);
        if (sums[k] != null && sums[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }
    // dp[i] represents the minimum cost to reach step i
    // We only need the last two values
    int prev2 = 0; // cost to reach step i-2
    int prev1 = 0; // cost to reach step i-1
    int curr = 0;
    for (int i = 2; i <= n; i++) {
        int costFromPrev1 = prev1 + cost[i - 1];
        int costFromPrev2 = prev2 + cost[i - 2];
        curr = Math.min(costFromPrev1, costFromPrev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return curr;
}

public int uniqueMorseRepresentations(String[] words) {
    // Morse code mapping for letters a-z
    String[] morse = {".-","-...","-.-.","-..",".","..-.","--.","....","..",
                      ".---","-.-",".-..","--","-.","---",".--.","--.-",".-.",
                      "...","-","..-","...-",".--","-..-","-.--","--.."};
    if (words == null || words.length == 0) {
        return 0;
    }
    java.util.Set<String> unique = new java.util.HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue; // skip null entries
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(morse[c - 'A']);
            } else {
                // ignore non-alphabetic characters
            }
        }
        unique.add(sb.toString());
    }
    return unique.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (k > n) {
        return false;
    }
    long total = 1L << k;
    // If the number of possible codes is too large to handle, return false
    if (total > Integer.MAX_VALUE) {
        return false;
    }
    long mask = (1L << k) - 1;
    long value = 0;
    java.util.Set<Long> seen = new java.util.HashSet<>();
    for (int i = 0; i < n; i++) {
        value = ((value << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen.add(value);
            if ((long) seen.size() == total) {
                return true;
            }
        }
    }
    return false;
}

