public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int balance = 0;      // number of unmatched '('
    int insertions = 0;   // number of insertions needed
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                // need an opening bracket before this ')'
                insertions++;
            } else {
                balance--; // match with an existing '('
            }
        } else {
            // ignore any other characters (though per spec there shouldn't be any)
        }
    }
    // any remaining unmatched '(' need closing brackets
    insertions += balance;
    return insertions;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    long halfN = n / 2L; // floor(n/2)
    long halfPrev = (n - 1) / 2L; // floor((n-1)/2)
    long result = halfN * (halfPrev + 1);
    if (result > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds int range");
    }
    return (int) result;
}

