public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    long maxSum = Long.MIN_VALUE;
    long minSum = Long.MAX_VALUE;
    long currentMax = 0;
    long currentMin = 0;
    for (int num : nums) {
        currentMax = Math.max(num, currentMax + num);
        maxSum = Math.max(maxSum, currentMax);
        currentMin = Math.min(num, currentMin + num);
        minSum = Math.min(minSum, currentMin);
    }
    long result = Math.max(maxSum, -minSum);
    // Clamp to int range if necessary
    if (result > Integer.MAX_VALUE) {
        return Integer.MAX_VALUE;
    }
    if (result < Integer.MIN_VALUE) {
        return Integer.MIN_VALUE;
    }
    return (int) result;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fib = new java.util.ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int size = fib.size();
        long next = (long) fib.get(size - 1) + fib.get(size - 2);
        if (next > k) {
            break;
        }
        fib.add((int) next);
    }
    // Greedy selection from largest to smallest
    int count = 0;
    int remaining = k;
    for (int i = fib.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fib.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            // Check if top and current are the same letter but opposite cases
            if (top != c && Character.toLowerCase(top) == Character.toLowerCase(c)) {
                stack.deleteCharAt(len - 1); // remove the pair
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int n = s.length();
    int max = 0;
    class State {
        int idx;
        int count;
        java.util.Set<String> used;
        State(int idx, int count, java.util.Set<String> used) {
            this.idx = idx;
            this.count = count;
            this.used = used;
        }
    }
    java.util.Deque<State> stack = new java.util.ArrayDeque<>();
    stack.push(new State(0, 0, new java.util.HashSet<>()));
    while (!stack.isEmpty()) {
        State cur = stack.pop();
        if (cur.idx == n) {
            if (cur.count > max) {
                max = cur.count;
            }
            continue;
        }
        for (int i = cur.idx; i < n; i++) {
            String sub = s.substring(cur.idx, i + 1);
            if (!cur.used.contains(sub)) {
                java.util.Set<String> newUsed = new java.util.HashSet<>(cur.used);
                newUsed.add(sub);
                stack.push(new State(i + 1, cur.count + 1, newUsed));
            }
        }
    }
    return max;
}

