        if ("../".equals(log)) {
            if (depth > 0) {
                depth--;
            }
        } else if ("./".equals(log)) {
            // stay in the same folder, do nothing
        } else if (log.endsWith("/")) {
            // enter a new folder
            depth++;
        } else {
            // ignore any malformed entry
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    // Validate input
    if (n <= 0) {
        throw new IllegalArgumentException("Length n must be positive.");
    }
    if (k < n || k > 26L * n) {
        throw new IllegalArgumentException("k must be between n and 26*n inclusive.");
    }

    char[] result = new char[n];
    // Initialize all characters to 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    int remaining = k - n; // amount of value we still need to add
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int increment = Math.min(25, remaining); // max we can add to this position
        result[i] = (char) ('a' + increment);
        remaining -= increment;
    }

    return new String(result);
}

