public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int bitCount = 0;
        for (int num : nums) {
            if (((num >> i) & 1) == 1) {
                bitCount++;
            }
        }
        if ((bitCount % 3) == 1) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    // Use long to avoid overflow during generation
    ArrayDeque<Long> queue = new ArrayDeque<>();
    // Start BFS from each digit 0-9
    for (int i = 0; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        if (num == 0) {
            // For 0, only generate 1 to avoid leading zeros
            if (1 <= high) {
                queue.offer(1);
            }
            continue;
        }
        int lastDigit = (int) (num % 10);
        // Next possible digits
        int[] nextDigits = {lastDigit - 1, lastDigit + 1};
        for (int next : nextDigits) {
            if (next < 0 || next > 9) {
                continue;
            }
            long newNum = num * 10 + next;
            if (newNum <= high) {
                queue.offer(newNum);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    long nLong = n;
    while (factor <= nLong) {
        long lower = nLong % factor;
        long cur = (nLong / factor) % 10;
        long higher = nLong / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A number is a power of two if it is positive and has exactly one bit set.
    // For n > 0, n & (n - 1) will be zero only for powers of two.
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    // Digital root formula: 0 -> 0, otherwise 1 + (num-1) % 9
    return num == 0 ? 0 : 1 + (num - 1) % 9;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    // dp[i][j][0] - horizontal, dp[i][j][1] - vertical,
    // dp[i][j][2] - diagonal, dp[i][j][3] - anti-diagonal
    int[][][] dp = new int[m][n][4];
    int maxLen = 0;
    try {
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    dp[i][j][0] = (j > 0) ? dp[i][j - 1][0] + 1 : 1;          // horizontal
                    dp[i][j][1] = (i > 0) ? dp[i - 1][j][1] + 1 : 1;          // vertical
                    dp[i][j][2] = (i > 0 && j > 0) ? dp[i - 1][j - 1][2] + 1 : 1; // diagonal
                    dp[i][j][3] = (i > 0 && j < n - 1) ? dp[i - 1][j + 1][3] + 1 : 1; // anti-diagonal
                    int cellMax = Math.max(Math.max(dp[i][j][0], dp[i][j][1]),
                                           Math.max(dp[i][j][2], dp[i][j][3]));
                    if (cellMax > maxLen) {
                        maxLen = cellMax;
                    }
                } else {
                    dp[i][j][0] = dp[i][j][1] = dp[i][j][2] = dp[i][j][3] = 0;
                }
            }
        }
    } catch (Exception e) {
        // In case of any unexpected runtime issue, return 0
        return 0;
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    // Handle zero explicitly
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    // Use long to avoid overflow when taking absolute value of Integer.MIN_VALUE
    long absVal = Math.abs((long) n);
    String s = Long.toString(absVal);
    int len = s.length();

    StringBuilder sb = new StringBuilder();

    // Determine the length of the first group (may be less than 3)
    int firstGroupLen = len % 3;
    if (firstGroupLen == 0) {
        firstGroupLen = 3;
    }

    // Append the first group
    sb.append(s.substring(0, firstGroupLen));

    // Append remaining groups, each preceded by a dot
    for (int i = firstGroupLen; i < len; i += 3) {
        sb.append('.');
        sb.append(s.substring(i, i + 3));
    }

    // Prepend negative sign if necessary
    if (negative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }
    int n = A.length;
    int[] sorted = A.clone();
    java.util.Arrays.sort(sorted);

    // Precompute which pairs sum to a perfect square
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int sum = sorted[i] + sorted[j];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                can[i][j] = can[j][i] = true;
            }
        }
    }

    boolean[] used = new boolean[n];
    int[] count = new int[1]; // use array to allow modification inside lambda

    java.util.function.BiConsumer<Integer, Integer> dfs = new java.util.function.BiConsumer<Integer, Integer>() {
        @Override
        public void accept(Integer depth, Integer lastIdx) {
            if (depth == n) {
                count[0]++;
                return;
            }
            for (int i = 0; i < n; i++) {
                if (used[i]) continue;
                if (depth > 0 && !can[lastIdx][i]) continue;
                // Skip duplicates: if current value equals previous and previous not used
                if (i > 0 && sorted[i] == sorted[i - 1] && !used[i - 1]) continue;
                used[i] = true;
                accept(depth + 1, i);
                used[i] = false;
            }
        }
    };

    for (int i = 0; i < n; i++) {
        used[i] = true;
        dfs.accept(1, i);
        used[i] = false;
    }

    return count[0];
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = heights.length;
    if (n == 0) {
        return 0;
    }
    int maxArea = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] result = new int[total];
    int idx = 0;
    int maxSum = m + n - 2;
    // Temporary array to hold elements of a diagonal
    int[] temp = new int[Math.min(m, n)];
    for (int sum = 0; sum <= maxSum; sum++) {
        int tIdx = 0;
        int row, col;
        if (sum < n) {
            row = 0;
            col = sum;
        } else {
            row = sum - n + 1;
            col = n - 1;
        }
        while (row < m && col >= 0) {
            temp[tIdx++] = mat[row][col];
            row++;
            col--;
        }
        if (sum % 2 == 0) {
            for (int i = tIdx - 1; i >= 0; i--) {
                result[idx++] = temp[i];
            }
        } else {
            for (int i = 0; i < tIdx; i++) {
                result[idx++] = temp[i];
            }
        }
    }
    return result;
}

public static java.util.List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new java.util.ArrayList<>();
    }
    return build(n, n);
}

private static java.util.List<String> build(int n, int m) {
    java.util.List<String> res = new java.util.ArrayList<>();
    if (n == 0) {
        res.add("");
        return res;
    }
    if (n == 1) {
        res.add("0");
        res.add("1");
        res.add("8");
        return res;
    }
    java.util.List<String> sub = build(n - 2, m);
    for (String s : sub) {
        if (n != m) {
            res.add("0" + s + "0");
        }
        res.add("1" + s + "1");
        res.add("8" + s + "8");
        res.add("6" + s + "9");
        res.add("9" + s + "6");
    }
    return res;
}

public static boolean isBoomerang(int[][] points) {
    // Validate input
    if (points == null || points.length != 3) {
        return false;
    }
    // Check for duplicate points
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
        for (int j = i + 1; j < 3; j++) {
            if (points[j] == null || points[j].length != 2) {
                return false;
            }
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false; // duplicate point
            }
        }
    }
    // Compute cross product to check collinearity
    long x1 = points[0][0], y1 = points[0][1];
    long x2 = points[1][0], y2 = points[1][1];
    long x3 = points[2][0], y3 = points[2][1];
    long cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    long next2 = 2L, next3 = 3L, next5 = 5L;
    for (int i = 1; i < n; i++) {
        long nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = (int) nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = (long) ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = (long) ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = (long) ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    java.util.Stack<Integer> stack = new java.util.Stack<>();
    // Initialize stack with numbers 9 to 1 (so that 1 is popped first)
    for (int i = 9; i >= 1; i--) {
        if (i <= n) {
            stack.push(i);
        }
    }
    while (!stack.isEmpty()) {
        int cur = stack.pop();
        result.add(cur);
        // Push children in reverse order to maintain lexicographic order
        for (int i = 9; i >= 0; i--) {
            long next = (long) cur * 10 + i;
            if (next <= n) {
                stack.push((int) next);
            }
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    long sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return (int) sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int prev = dp[i - square];
            if (prev != Integer.MAX_VALUE && prev + 1 < dp[i]) {
                dp[i] = prev + 1;
            }
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(' ');
        } else {
            word.append(c);
        }
    }
    result.append(word.reverse());
    return result.toString();
}
